import torch, numpy as np, b200probe as bp
src = r'''
__device__ __forceinline__ unsigned long long gt(){unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;":"=l"(t)); return t;}
__device__ __forceinline__ unsigned ldacq(const unsigned* p){unsigned v; asm volatile("ld.acquire.gpu.global.u32 %0,[%1];":"=r"(v):"l"(p):"memory"); return v;}
__device__ void gbar(unsigned* bar, int G){
  __syncthreads();
  if(threadIdx.x==0){
    unsigned g = ldacq(bar+1);
    __threadfence();
    if(atomicAdd(bar,1u)==(unsigned)G-1){ bar[0]=0; __threadfence(); atomicAdd(bar+1,1u);} 
    else { while(ldacq(bar+1)==g){} }
  }
  __syncthreads();
}
#define ST(i) if(threadIdx.x==0){ts[blockIdx.x*16+(i)]=gt(); ts[blockIdx.x*16+8+(i)]=clock64();}
extern "C" __global__ void __launch_bounds__(256,2) mb(float* bufw, const float* bufc, unsigned* bar, unsigned long long* ts,
   int mode, int nbytes, int src_sel, int prestore, int K8){
  __shared__ __align__(128) float sbuf[9472];
  __shared__ __align__(8) unsigned long long mbar;
  const int tid=threadIdx.x, G=gridDim.x, bid=blockIdx.x;
  const unsigned sb=(unsigned)__cvta_generic_to_shared(sbuf), mbs=(unsigned)__cvta_generic_to_shared(&mbar);
  if(tid==0){ asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;"::"r"(mbs)); asm volatile("fence.mbarrier_init.release.cluster;"); }
  __syncthreads();
  ST(0)
  const int n16 = nbytes>>4;
  if(prestore){ float4* d=(float4*)(bufw+(size_t)bid*8192); for(int i=tid;i<n16;i+=256) d[i]=make_float4(bid,i,1.f,2.f); }
  ST(1)
  gbar(bar,G);
  ST(2)
  const float* src = src_sel==0 ? bufw+(size_t)((bid+G/2+1)%G)*8192 : bufc+(size_t)bid*8192;
  if(mode==1){ // 4-byte cp.async with div/mod and padded rows (K8*8 floats per row)
    const int K=K8*8, nf=nbytes>>2;
    for(int i=tid;i<nf;i+=256){ int r=i/K, k=i-r*K; asm volatile("cp.async.ca.shared.global [%0],[%1],4;"::"r"(sb+(r*(K+4)+k)*4),"l"(src+i):"memory"); }
    asm volatile("cp.async.commit_group;\ncp.async.wait_group 0;":::"memory");
  } else if(mode==2){ // 16-byte cp.async, parent's i/K8 index maths
    for(int i=tid;i<n16;i+=256){ int r=i/K8, k8=i-r*K8; asm volatile("cp.async.cg.shared.global [%0],[%1],16;"::"r"(sb+(r*(K8*8+8)+k8*8)*4),"l"(src+i*4):"memory"); }
    asm volatile("cp.async.commit_group;\ncp.async.wait_group 0;":::"memory");
  } else if(mode==3){ // LDG.128 all issued first
    float4 r[8]; const float4* s4=(const float4*)src;
#pragma unroll
    for(int j=0;j<8;j++){ int i=tid+j*256; if(i<n16) r[j]=__ldg(s4+i); }
#pragma unroll
    for(int j=0;j<8;j++){ int i=tid+j*256; if(i<n16) ((float4*)sbuf)[i]=r[j]; }
  } else if(mode==4){ // one bulk copy + mbarrier
    if(tid==0){
      asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;"::"r"(mbs),"r"(nbytes):"memory");
      asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0],[%1],%2,[%3];"::"r"(sb),"l"(src),"r"(nbytes),"r"(mbs):"memory");
    }
    asm volatile("{ .reg .pred p; LW%=: mbarrier.try_wait.parity.shared::cta.b64 p, [%0], 0; @!p bra LW%=; }"::"r"(mbs):"memory");
  }
  __syncthreads();
  ST(3)
  if(tid==0) ts[bid*16+7]=__float_as_uint(sbuf[5]);
}
'''
k = bp.cuda_kernel(src, "mb")
G=296
bufw=torch.zeros(G*8192,device='cuda'); bufc=torch.randn(G*8192,device='cuda'); bar=torch.zeros(4,dtype=torch.int32,device='cuda')
ts=torch.zeros(G*16,dtype=torch.int64,device='cuda')
def run(mode,nb,src_sel,pre,reps=7):
    res=[]
    for r in range(reps):
        bp.flush_l2(); torch.cuda.synchronize()
        k((G,),(256,),bufw,bufc,bar,ts,mode,nb,src_sel,pre,8 if nb>=8192 else 4)
        torch.cuda.synchronize()
        t=ts.view(G,16).cpu().numpy().astype(np.float64)
        g=t[:,:4]; c=t[:,8:12]
        rnd=g[:,3]-g[:,2]; rc=c[:,3]-c[:,2]
        bars=g[:,2]-g[:,1]; rel=g[:,2].max()-g[:,1].max(); relmin=g[:,2].min()-g[:,1].max()
        clk=np.median((c[:,3]-c[:,0])/np.maximum(g[:,3]-g[:,0],1))
        res.append([np.median(rnd),rnd.max(),np.median(rc),rc.max(),np.median(bars),relmin,rel,g[:,3].max()-g[:,0].min(),clk])
    return np.median(np.array(res),axis=0)
names={0:'none',1:'cp4+div',2:'cp16+div',3:'ldg128',4:'bulk'}
print("bar-only: med round, ... | bar wait med, release(min,max) after last arrival ns, span, GHz")
for pre in (0,1):
    for nb in (6144,32768):
        r=run(0,nb,1,pre); print(f"barrier only prestore={pre} {nb//1024}KB: barwait_med {r[4]:.0f} rel_min {r[5]:.0f} rel_max {r[6]:.0f} span {r[7]:.0f} clk {r[8]:.2f}")
print("cell: src mode KB | round med/max ns | med/max clk | B/clk/SM (2 CTAs) | span ns")
for src_sel,pre,lab in ((0,1,'justwritten'),(1,0,'cold')):
    for nb in (6144,12288,32768):
        for mode in (1,2,3,4):
            r=run(mode,nb,src_sel,pre)
            print(f"{lab:11s} {names[mode]:8s} {nb//1024:2d}KB | {r[0]:6.0f} {r[1]:6.0f} | {r[2]:6.0f} {r[3]:6.0f} | {2*nb/r[2]:5.1f} | span {r[7]:.0f} rel {r[6]:.0f}")

