    case 1: flat_gemm2<64, 96, 2, 4>(p, sm, p.split3, nf, gws, mbar, ph); break;
    case 2: flat_gemm2<128, 96, 4, 2>(p, sm, p.split3, nf, gws, mbar, ph); break;
