  const G g2[5] = {{0, 64, 64}, {1, 64, 96}, {2, 128, 96}, {3, 64, 192}, {4, 64, 160}};
  double best1 = 1e300, best2 = 1e300; int c1 = -1, c2 = -1, s2 = 1;
