      const long units = ((M + g.BM - 1) / g.BM) * (C / g.BN) * s, waves = (units + grid - 1) / grid;
      if (waves > 2) continue;
      const double cost = waves * ((double)g.BM * g.BN * KSL / 512.0 + (g.BM + g.BN) * KSL * 2 / 64.0 + g.BM * g.BN / 64.0 + 1500.0);
      if (cost < best2) { best2 = cost; c2 = g.id; s2 = s; }
